package com.food.controller;
import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*;
@Controller public class LoginController { @Autowired private JdbcTemplate jdbcTemplate; @GetMapping("/login") public String login(){return "login";} @PostMapping("/login") public String doLogin(@RequestParam String username,@RequestParam String password,HttpSession session){ Integer count=jdbcTemplate.queryForObject("SELECT COUNT(*) FROM users WHERE username=? AND password=?",Integer.class,username,password); if(count!=null&&count>0){session.setAttribute("username",username);return "redirect:/dashboard";} return "redirect:/login?error=1";} @GetMapping("/logout") public String logout(HttpSession session){session.invalidate();return "redirect:/login";} }
